//! Textures. The environment set (colour, normal and roughness maps) is
//! generated by `tools/make_textures.py` in the palette of
//! `art/environment-reference.png` and embedded in the binary, so no
//! platform loads files at runtime. The HUD sword is still drawn here.

use bevy::asset::RenderAssetUsages;
use bevy::image::{CompressedImageFormats, ImageSampler, ImageType};
use bevy::prelude::*;
use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};
use zrpg_core::rng::mix64;

/// One surface's maps: colour (sRGB), tangent-space normals and packed
/// occlusion/roughness/metallic (both linear).
#[derive(Clone, Copy)]
pub struct Maps {
    pub color: &'static [u8],
    pub normal: &'static [u8],
    pub orm: &'static [u8],
}

/// The embedded environment textures.
pub mod env {
    use super::Maps;

    macro_rules! maps {
        ($name:literal) => {
            Maps {
                color: include_bytes!(concat!("../assets/env/", $name, ".png")),
                normal: include_bytes!(concat!("../assets/env/", $name, "_n.png")),
                orm: include_bytes!(concat!("../assets/env/", $name, "_orm.png")),
            }
        };
    }
    pub const WALLS: [Maps; 4] = [
        maps!("wall"),
        maps!("wall_mossy"),
        maps!("wall_cracked"),
        maps!("wall_carved"),
    ];
    pub const FLOORS: [Maps; 2] = [maps!("floor"), maps!("floor_mossy")];
    pub const CEILING: Maps = maps!("ceiling");
    pub const STAIRS: Maps = maps!("stairs");
    pub const ARCH: Maps = maps!("arch");
    pub const VINES: Maps = maps!("vines");
    pub const FERN: Maps = maps!("fern");
    pub const SCONCE: Maps = maps!("sconce");
    pub const FLAME: &[u8] = include_bytes!("../assets/env/flame.png");
}

/// Decode an embedded colour PNG (sRGB, nearest-neighbour by default).
pub fn embedded(png: &[u8]) -> Image {
    decode(png, true)
}

/// Decode an embedded data PNG (normals, roughness): linear, not sRGB.
pub fn embedded_linear(png: &[u8]) -> Image {
    decode(png, false)
}

fn decode(png: &[u8], srgb: bool) -> Image {
    Image::from_buffer(
        png,
        ImageType::Extension("png"),
        CompressedImageFormats::NONE,
        srgb,
        ImageSampler::Default,
        RenderAssetUsages::RENDER_WORLD,
    )
    .expect("embedded textures are valid PNGs")
}

/// Deterministic per-pixel noise in `-1.0..1.0`.
fn noise(salt: u64, x: u32, y: u32) -> f32 {
    let h = mix64(salt ^ ((x as u64) << 32 | y as u64));
    (h & 0xFFFF) as f32 / 32767.5 - 1.0
}

/// `None` pixels are fully transparent (for alpha-masked sprites).
fn build_rgba(
    w: u32,
    h: u32,
    salt: u64,
    pixel: impl Fn(u32, u32, f32) -> Option<[u8; 3]>,
) -> Image {
    let mut data = Vec::with_capacity((w * h * 4) as usize);
    for y in 0..h {
        for x in 0..w {
            match pixel(x, y, noise(salt, x, y)) {
                Some([r, g, b]) => data.extend_from_slice(&[r, g, b, 255]),
                None => data.extend_from_slice(&[0, 0, 0, 0]),
            }
        }
    }
    Image::new(
        Extent3d {
            width: w,
            height: h,
            depth_or_array_layers: 1,
        },
        TextureDimension::D2,
        data,
        TextureFormat::Rgba8UnormSrgb,
        RenderAssetUsages::RENDER_WORLD,
    )
}

fn shade(base: [u8; 3], k: f32) -> [u8; 3] {
    base.map(|c| (c as f32 * k).clamp(0.0, 255.0) as u8)
}

/// The player's sword, held point-up, for the first-person hand overlay.
pub const SWORD_SIZE: (u32, u32) = (16, 48);

pub fn sword() -> Image {
    let (w, h) = SWORD_SIZE;
    build_rgba(w, h, 8, |x, y, n| {
        let cx = (x as i32 - 7).abs();
        match y {
            // Point.
            0..=3 if cx as u32 <= y / 2 => Some(shade([210, 214, 224], 1.0 + n * 0.05)),
            // Blade with a darker fuller down the middle.
            4..=31 if cx <= 2 => {
                let k = if cx == 0 {
                    0.75
                } else if x < 7 {
                    1.1
                } else {
                    0.9
                };
                Some(shade([196, 200, 212], k + n * 0.05))
            }
            // Crossguard.
            32..=34 if cx <= 7 => Some(shade([150, 112, 40], 1.0 - (y - 32) as f32 * 0.15)),
            // Grip.
            35..=44 if cx <= 1 => Some(shade([84, 50, 30], if y % 2 == 0 { 1.0 } else { 0.7 })),
            // Pommel.
            45..=47 if cx <= 2 => Some(shade([170, 130, 50], 1.0)),
            _ => None,
        }
    })
}
